customJs:
function onMount(el, props) {
  const root = el.querySelector('#notif-root');
  const promptBox = el.querySelector('#notif-prompt-box');
  const statusBox = el.querySelector('#notif-status-box');
  const allowBtn = el.querySelector('#notif-allow-btn');
  const denyBtn = el.querySelector('#notif-deny-btn');
  const closeBtn = el.querySelector('#notif-close-btn');

  function urlBase64ToUint8Array(base64String) {
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const rawData = window.atob(base64);
    const outputArray = new Uint8Array(rawData.length);
    for (let i = 0; i < rawData.length; ++i) {
      outputArray[i] = rawData.charCodeAt(i);
    }
    return outputArray;
  }

  // Check environment support
  if (!('serviceWorker' in navigator) || !('PushManager' in window) || !('Notification' in window)) {
    return; // Silently fail if browser doesn't support notifications
  }

  // 1. Persistence Check
  const hasInteracted = localStorage.getItem('aether_notif_interacted');
  const currentPermission = Notification.permission;

  if (hasInteracted === 'true' || currentPermission !== 'default') {
    return; // Don't show the toast at all
  }

  // 2. Show the toast
  root.style.display = 'block';

  // 3. Auto-hide after 5 seconds
  let autoHideTimer = setTimeout(function() {
    root.style.display = 'none';
  }, 5000);

  function hideToast() {
    clearTimeout(autoHideTimer);
    root.style.display = 'none';
  }

  // 4. Event Listeners
  closeBtn.addEventListener('click', function() {
    hideToast();
    localStorage.setItem('aether_notif_interacted', 'true'); // Persist on close
  });

  denyBtn.addEventListener('click', function() {
    hideToast();
    localStorage.setItem('aether_notif_interacted', 'true'); // Persist on deny
  });

  allowBtn.addEventListener('click', function() {
    hideToast();
    localStorage.setItem('aether_notif_interacted', 'true'); // Persist on allow

    Notification.requestPermission().then(function(permission) {
      if (permission === 'granted') {
        // Register Service Worker
        navigator.serviceWorker.register('/sw.js').then(function(reg) {
          const subscribeOptions = {
            userVisibleOnly: true,
            applicationServerKey: urlBase64ToUint8Array(props.vapidPublicKey)
          };
          return reg.pushManager.subscribe(subscribeOptions);
        }).then(function(subscription) {
          console.log('Subscribed successfully:', subscription);
          // TODO: Send subscription to your backend via fetch()
          /*
          fetch('https://yourdomain.com/api/save-subscription', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(subscription)
          });
          */
        }).catch(function(err) {
          console.error('Subscription failed:', err);
        });
      }
    });
  });
}

