  font-size: 1rem;
}

/* ── SVG curve divider (used when no bg image OR user disables adoption) ── */
.wb-addon-ultra_nav_header .nav-shape-divider {
  position: absolute;
  top: 100%;
  left: 0;
  width: 100%;
  height: clamp(0px, var(--curve-height, 36px), 120px);
  overflow: hidden;
  line-height: 0;
  pointer-events: none;
  z-index: 5;
  filter: drop-shadow(0 4px 8px rgba(0,0,0,0.18));
  transition: height 0.3s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.3s ease;
}

.wb-addon-ultra_nav_header .nav-shape-divider .shape-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.wb-addon-ultra_nav_header .nav-shape-divider .shape-svg.shape-arch {
  display: none;
}

.wb-addon-ultra_nav_header .nav-shape-divider[data-curve="arch"] .shape-wave {
  display: none;
}

.wb-addon-ultra_nav_header .nav-shape-divider[data-curve="arch"] .shape-arch {
  display: block;
}

/* ── Curve rendering modes ─────────────────────────────────────── */
/* ADOPT: clip the entire header/background to the selected curve shape. */
.wb-addon-ultra_nav_header.curve-mode-adopt .nav-shape-divider {
  display: none;
}

.wb-addon-ultra_nav_header.curve-mode-adopt {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - var(--curve-height, 36px)), 0 calc(100% - var(--curve-height, 36px)));
}

.wb-addon-ultra_nav_header.curve-mode-adopt[data-curve="wave"] {
  clip-path: polygon(
    0 0, 100% 0, 100% calc(100% - 8px),
    75% calc(100% - 8px), 50% calc(100% - var(--curve-height, 36px)),
    25% calc(100% - 8px), 0 calc(100% - 8px)
  );
}

.wb-addon-ultra_nav_header.curve-mode-adopt[data-curve="arch"] {
  clip-path: polygon(
    0 0, 100% 0, 100% calc(100% - var(--curve-height, 36px)),
    75% calc(100% - var(--curve-height, 36px)), 50% calc(100% - 8px),
    25% calc(100% - var(--curve-height, 36px)), 0 calc(100% - var(--curve-height, 36px))
  );
}

/* IMAGE: the SVG retains its wave/arch geometry and receives an SVG image pattern. */
.wb-addon-ultra_nav_header.curve-mode-image .nav-shape-divider {
  display: block;
}
.wb-addon-ultra_nav_header.curve-mode-image .nav-shape-divider .curve-fill {
  fill: var(--curve-image-fill, currentColor);
}

/* SOLID: the original SVG color divider remains active. */
.wb-addon-ultra_nav_header.curve-mode-solid .nav-shape-divider {
  display: block;
}

/* Backward compatibility for older saved instances using the previous class. */
.wb-addon-ultra_nav_header.curve-clipped .nav-shape-divider { display: none; }

.wb-addon-ultra_nav_header.scrolled {
  box-shadow: 0 8px 32px rgba(0,0,0,0.4) !important;
}

.wb-addon-ultra_nav_header.scrolled .nav-shape-divider {
  height: 12px;
  opacity: 0.95;
}

.wb-addon-ultra_nav_header.is-on-top {
  z-index: 99999 !important;
}

.canvas-section-wrapper:has(.wb-addon-ultra_nav_header.is-sticky),
.canvas-section-wrapper.is-sticky-section {
  position: -webkit-sticky !important;
  position: sticky !important;
  top: 0px !important;
  z-index: 9999 !important;
  padding: 0px !important;
  margin: 0px !important;
}

.canvas-section-wrapper:has(.wb-addon-ultra_nav_header.is-sticky) .canvas-section-content,
.canvas-section-wrapper.is-sticky-section .canvas-section-content {
  max-width: 100% !important;
  width: 100% !important;
  padding: 0px !important;
}

@keyframes unav-slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes unav-fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

