function onMount(el, props) {
  // ── Curve mode controller (v7.0) ─────────────────────────────────
  // Modes: solid = original colored SVG; image = image-filled SVG;
  // adopt = clip the complete header/background to the curve shape.
  var truthy = function(v) { return v === true || v === 'true' || v === 1 || v === '1'; };
  var mode = props.curveMode;
  // Legacy compatibility: older saved widgets only have curveUseBgImage.
  if (!mode) mode = truthy(props.curveUseBgImage) ? 'adopt' : 'solid';
  if (['solid', 'image', 'adopt'].indexOf(mode) === -1) mode = 'solid';
  var curveEnabled = truthy(props.showCurveDivider);
  el.classList.remove('curve-mode-solid', 'curve-mode-image', 'curve-mode-adopt', 'curve-clipped');
  if (curveEnabled) el.classList.add('curve-mode-' + mode);
  el.setAttribute('data-curve', props.curveStyle || 'wave');
  var divider = el.querySelector('.nav-shape-divider');
  if (divider) divider.setAttribute('data-curve', props.curveStyle || 'wave');

  // Build an image pattern inside each SVG so multiple header instances
  // never share SVG IDs. The SVG path itself defines the exact curve mask.
  if (curveEnabled && mode === 'image' && divider) {
    var curveImage = props.curveBackgroundImage;
    if (!curveImage && truthy(props.curveImageUseHeader)) curveImage = props.bgImage;
    if (curveImage) {
      var svgs = divider.querySelectorAll('.shape-svg');
      var ns = 'http://www.w3.org/2000/svg';
      var unique = 'unav-curve-' + Math.random().toString(36).slice(2);
      var fit = props.curveImageSize || 'cover';
      var position = props.curveImagePosition || 'center';
      var preserve = 'xMidYMid slice';
      if (fit === 'contain') preserve = 'xMidYMid meet';
      if (fit === 'stretch') preserve = 'none';
      if (position === 'top') preserve = preserve.replace('YMid', 'YMin');
      if (position === 'bottom') preserve = preserve.replace('YMid', 'YMax');
      if (position === 'left') preserve = preserve.replace('xMid', 'xMin');
      if (position === 'right') preserve = preserve.replace('xMid', 'xMax');
      Array.prototype.forEach.call(svgs, function(svg, index) {
        var defs = document.createElementNS(ns, 'defs');
        var pattern = document.createElementNS(ns, 'pattern');
        var patternId = unique + '-' + index;
        pattern.setAttribute('id', patternId);
        pattern.setAttribute('patternUnits', 'userSpaceOnUse');
        pattern.setAttribute('x', '0'); pattern.setAttribute('y', '0');
        pattern.setAttribute('width', '1440'); pattern.setAttribute('height', '48');
        var image = document.createElementNS(ns, 'image');
        image.setAttribute('x', '0'); image.setAttribute('y', '0');
        image.setAttribute('width', '1440'); image.setAttribute('height', '48');
        image.setAttribute('preserveAspectRatio', preserve);
        image.setAttributeNS('http://www.w3.org/1999/xlink', 'xlink:href', curveImage);
        image.setAttribute('href', curveImage);
        pattern.appendChild(image);
        var overlayOpacity = Number(props.curveImageOverlayOpacity || 0);
        if (overlayOpacity > 0) {
          var overlay = document.createElementNS(ns, 'rect');
          overlay.setAttribute('x', '0'); overlay.setAttribute('y', '0');
          overlay.setAttribute('width', '1440'); overlay.setAttribute('height', '48');
          overlay.setAttribute('fill', props.curveImageOverlayColor || '#000000');
          overlay.setAttribute('opacity', String(Math.max(0, Math.min(1, overlayOpacity))));
          pattern.appendChild(overlay);
        }
        defs.appendChild(pattern);
        svg.insertBefore(defs, svg.firstChild);
        var fillPath = svg.querySelector('.curve-fill');
        if (fillPath) fillPath.setAttribute('fill', 'url(#' + patternId + ')');
      });
    }
  }
  var isSticky = props.stickyHeader === true || props.stickyHeader === 'true';
  var secWrapper = el.closest('.canvas-section-wrapper') || el.parentElement;

  if (isSticky && secWrapper) {
    secWrapper.style.setProperty('position', 'sticky', 'important');
    secWrapper.style.setProperty('top', '0px', 'important');
    secWrapper.style.setProperty('z-index', '9999', 'important');
    secWrapper.style.setProperty('padding', '0px', 'important');
    secWrapper.style.setProperty('margin', '0px', 'important');
    el.style.setProperty('width', '100%', 'important');
    el.style.setProperty('max-width', '100%', 'important');
    el.style.setProperty('padding', '0px', 'important');
  }

  var toggleBtn = el.querySelector('.mobile-toggle');
  var drawer = el.querySelector('.mobile-drawer');
  if (toggleBtn && drawer) {
    toggleBtn.addEventListener('click', function(e) {
      e.stopPropagation();
      var isOpen = drawer.classList.toggle('is-open');
      toggleBtn.classList.toggle('is-active', isOpen);
      toggleBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
    });
  }

  if (isSticky) {
    var headerEl = el;
    var checkScroll = function() {
      var scrollY = window.pageYOffset || document.documentElement.scrollTop || 0;
      var vp = document.querySelector('.builder-canvas-viewport');
      var isScrolled = (vp && vp.scrollTop > 10) || (scrollY > 10);
      if (headerEl) {
        if (isScrolled) headerEl.classList.add('scrolled');
        else headerEl.classList.remove('scrolled');
      }
    };

    window.addEventListener('scroll', checkScroll, { passive: true });
    var vp = document.querySelector('.builder-canvas-viewport');
    if (vp) vp.addEventListener('scroll', checkScroll, { passive: true });
    checkScroll();
  }
}

